package com.library; import org.apache.ibatis.annotations.*; import java.util.*;
@Mapper public interface BorrowRecordMapper { @Select("SELECT br.*,COALESCE(u.user_name,rd.reader_name) AS borrowerUsername FROM borrow_record br LEFT JOIN library_user u ON br.reader_id=u.id LEFT JOIN reader rd ON br.reader_id=rd.id ORDER BY br.id DESC") List<Map<String,Object>> list(); @Select("SELECT COUNT(*) FROM borrow_record WHERE reader_id=#{readerId} AND status='BORROWED'") int activeReaderCount(Long readerId); @Select("SELECT * FROM borrow_record WHERE id=#{id}") Map<String,Object> get(Long id); @Insert("INSERT INTO borrow_record(book_id,reader_id,borrow_time,due_time,status) VALUES(#{bookId},#{readerId},#{borrowTime},#{dueTime},'BORROWED')") @Options(useGeneratedKeys=true,keyProperty="id") int insert(Map<String,Object> r); @Update("UPDATE borrow_record SET return_time=#{returnTime},status='RETURNED' WHERE id=#{id} AND status='BORROWED' AND return_time IS NULL") int returnBook(Map<String,Object> r); }
